func afRect(res *port.Cells, x0 int32, y0 int32, x1 int32, y1 int32, dpi int32, maxpix int32) int32 {
	// `as-render-rect` of a region of a 612 x 792 pt page: d, px, py, pw, ph into `res`.
	var rc *port.Cells = port.NewCells()
	port.CellsPush(rc, 0)
	port.CellsPush(rc, 0)
	port.CellsPush(rc, 0)
	port.CellsPush(rc, 0)
	port.CellsDrop(res, 0)
	port.CellsPush(res, asset.AsRenderRect(x0, y0, x1, y1, 61200, 79200, dpi, maxpix, rc))
	port.CellsPush(res, port.CellsAt(rc, 0))
	port.CellsPush(res, port.CellsAt(rc, 1))
	port.CellsPush(res, port.CellsAt(rc, 2))
	port.CellsPush(res, port.CellsAt(rc, 3))
	return 0
}

func TestTheRenderRectangleIsPaddedFlooredCeiledAndHeldToThePage(emonT *testing.T) {
	var res *port.Cells = port.NewCells()
	afRect(res, 10000, 10000, 30000, 30000, 150, 4194304)
	port.AssertEq(emonT, port.CellsAt(res, 0), 150, "the setting's dpi when it fits")
	port.AssertEq(emonT, port.CellsAt(res, 1), 204, "px = floor(9800 * 150 / 7200)")
	port.AssertEq(emonT, port.CellsAt(res, 2), 204, "py likewise")
	port.AssertEq(emonT, port.CellsAt(res, 3), 426, "pw = ceil(30200 * 150 / 7200) - px = 630 - 204")
	port.AssertEq(emonT, port.CellsAt(res, 4), 426, "ph likewise")
	// the pad is clipped to the page: a region at the corner starts at pixel 0
	afRect(res, 0, 0, 1000, 1000, 150, 4194304)
	port.AssertEq(emonT, port.CellsAt(res, 1), 0, "px 0")
	port.AssertEq(emonT, port.CellsAt(res, 3), 25, "ceil(1200 * 150 / 7200) = 25")
	// and its far edge is the whole page's size, floor(w * d / 7200 + 1/2) pixels (1275 at 150 dpi)
	afRect(res, 60000, 78000, 61200, 79200, 150, 4194304)
	port.AssertEq(emonT, port.CellsAt(res, 1), 1245, "px = floor(59800 * 150 / 7200)")
	port.AssertEq(emonT, port.CellsAt(res, 3), 30, "to the page's edge, pixel 1275")
	port.AssertEq(emonT, port.CellsAt(res, 4), 30, "in y too")
}

func TestTooManyPixelsStepTheDpiDownByThreeQuarters(emonT *testing.T) {
	var res *port.Cells = port.NewCells()
	afRect(res, 10000, 10000, 30000, 30000, 150, 100000)
	port.AssertEq(emonT, port.CellsAt(res, 0), 84, "150 -> 112 (426 squared is over 100000, 318 squared too) -> 84")
	port.AssertEq(emonT, port.CellsAt(res, 1), 114, "px at 84 dpi")
	port.AssertEq(emonT, port.CellsAt(res, 3), 239, "pw at 84 dpi: 239 * 239 fits")
	afRect(res, 10000, 10000, 30000, 30000, 150, 100)
	port.AssertEq(emonT, port.CellsAt(res, 0), 0, "under 36 dpi: too large")
	afRect(res, 10000, 20000, 40000, 50000, 72, 4194304)
	port.AssertEq(emonT, port.CellsAt(res, 0), 72, "the given dpi, not 150")
	port.AssertEq(emonT, port.CellsAt(res, 3), 304, "304 pixels across")
	afRect(res, 5000, 5000, 5000, 5000, 150, 4194304)
	port.AssertEq(emonT, port.CellsAt(res, 0), 150, "a point is still a rectangle (the pad makes it one)")
}

func afPx(x int32, y int32, c int32) int32 {
	// The pattern of the frames and the renders: a pixel that tells where it is.
	return ((x * 7) + ((y * 13) + (c * 29))) & 255
}

func afFill(b *port.Bitmap, w int32, h int32, ch int32) int32 {
	var x int32 = 0
	var y int32 = 0
	var c int32 = 0
	for y < h {
		x = 0
		for x < w {
			c = 0
			for c < ch {
				port.BitmapSetU8(b, x, y, c, afPx(x, y, c))
				c += 1
			}
			x += 1
		}
		y += 1
	}
	return 0
}

func afNode(nodes *port.Cells, regions *port.Cells, parent int32, kind int32, sub int32, page int32, x0 int32, y0 int32, x1 int32, y1 int32) int32 {
	var n int32 = model.NodeNew(nodes, kind, parent)
	model.NodeSetSub(nodes, n, sub)
	if page >= 0 {
		model.NodeAddRegion(nodes, regions, n, page, x0, y0, x1, y1)
	}
	return n
}

func afText(nodes *port.Cells, regions *port.Cells, page int32, x0 int32, y0 int32, x1 int32, y1 int32) int32 {
	// A paragraph with a text run (an empty one: it is the run's existence that says a node has text) and a region.
	var n int32 = model.NodeNew(nodes, model.NkParagraph(), 0)
	model.NodeSetText(nodes, n, 0, 0)
	model.NodeAddRegion(nodes, regions, n, page, x0, y0, x1, y1)
	return n
}

