func TestAVectorFigureAsksForACropAndIsTheBitmap(emonT *testing.T) {
	var res *port.Cells = port.NewCells()
	afPdf(res, 0, 150, 4194304, 0)
	port.AssertEq(emonT, port.CellsAt(res, 0), 1, "one request")
	port.AssertEq(emonT, port.CellsAt(res, 1), plan.PkCrop(), "a crop")
	port.AssertEq(emonT, port.CellsAt(res, 2), plan.AuId(1), "under the asset unit's id of the node")
	port.AssertEq(emonT, port.CellsAt(res, 3), 3, "of the input")
	port.AssertEq(emonT, port.CellsAt(res, 4), 0, "page 0 (0-based)")
	port.AssertEq(emonT, port.CellsAt(res, 5), 150, "at asset-dpi")
	port.AssertEq(emonT, port.CellsAt(res, 6), 0, "with text")
	port.AssertEq(emonT, port.CellsAt(res, 7), 204, "px")
	port.AssertEq(emonT, port.CellsAt(res, 8), 204, "py")
	port.AssertEq(emonT, port.CellsAt(res, 9), 426, "pw")
	port.AssertEq(emonT, port.CellsAt(res, 10), 426, "ph")
	afPdf(res, 1, 150, 4194304, 0)
	port.AssertEq(emonT, port.CellsAt(res, 0), 0, "answered: nothing more is asked")
	port.AssertEq(emonT, port.CellsAt(res, 11), 0, "the figure has asset 0")
	port.AssertEq(emonT, port.CellsAt(res, 12), -1, "and no reason")
	port.AssertEq(emonT, port.CellsAt(res, 13), model.AoRendered(), "rendered")
	port.AssertEq(emonT, port.CellsAt(res, 14), model.AfmRender(), "from the render")
	port.AssertEq(emonT, port.CellsAt(res, 15), 426, "the bitmap's width")
	port.AssertEq(emonT, port.CellsAt(res, 16), 426, "its height")
	port.AssertEq(emonT, port.CellsAt(res, 17), 150, "at the dpi it was asked at")
	port.AssertEq(emonT, port.CellsAt(res, 18), 0, "no body text is over it")
}

