func afSource(res *port.Cells, which int32) int32 {
	// One figure that is the candidate `which` names, no answers; the number of requests it makes and its reason (or -1):
	// 0 a whole image (status 0, no flags): its own, no request; 1 the same with `overlaid`; 2 `colorspace`; 3 `codec`; 4 `part` (page-sized);
	// 5 `too-large`; 6 `budget`; 7 a region candidate; 8 a whole image that is `clip-bbox`; 9 `transformed`.
	var nodes *port.Cells = port.NewCells()
	var attrs *port.Cells = port.NewCells()
	var regions *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var pages *port.Cells = port.NewCells()
	var ledger *port.Cells = port.NewCells()
	var layout *port.Cells = port.NewCells()
	var assets *port.Cells = port.NewCells()
	var uses *port.Cells = port.NewCells()
	var cand *port.Cells = port.NewCells()
	var ans *port.Cells = port.NewCells()
	var rq *port.Cells = port.NewCells()
	var box *port.Cells = port.NewCells()
	var ws *port.Cells = port.NewCells()
	var rows *port.Cells = port.NewCells()
	var tmp *port.Cells = port.NewCells()
	var rec *port.Cells = port.NewCells()
	var cbytes *port.Buf = port.NewBuf()
	var abytes *port.Buf = port.NewBuf()
	var z *port.Buf = port.NewBuf()
	var bms *port.BitmapSet = port.NewBitmapSet()
	var status int32 = 0
	var flags int32 = 0
	var kori int32 = -1
	var n int32 = 0
	model.ModelInit(nodes, attrs, regions, text, pages, ledger, layout)
	model.PageNew(pages, 1, 61200, 79200, 0, model.PkVector())
	port.BufPush(cbytes, 97)
	port.BufPush(cbytes, 97)
	port.BufPush(cbytes, 97)
	port.BufPush(cbytes, 97)
	if which == 1 {
		flags = model.AfgOverlaid()
	}
	if which == 2 {
		status = model.NzColorspace()
	}
	if which == 3 {
		status = model.NzCodec()
	}
	if which == 4 {
		status = model.NzPart()
	}
	if which == 5 {
		status = model.NzTooLarge()
	}
	if which == 6 {
		status = model.NzBudget()
	}
	if which == 7 {
		status = model.NzVector()
		kori = -2
	}
	if which == 8 {
		flags = 2
	}
	if which == 9 {
		flags = 4
	}
	if which == 4 {
		afCand(cand, 1, 0, 0, 61200, 79200, status, flags, kori, 5, 0, 4)
	} else {
		afCand(cand, 1, 10000, 10000, 30000, 30000, status, flags, kori, 5, 0, 4)
	}
	if which == 4 {
		n = afNode(nodes, regions, 0, model.NkFigure(), model.FgUnknown(), 1, 0, 0, 61200, 79200)
	} else {
		n = afNode(nodes, regions, 0, model.NkFigure(), model.FgUnknown(), 1, 10000, 10000, 30000, 30000)
	}
	model.NodeSetAttrInt(nodes, attrs, n, model.FkImage(), 0)
	afBoxcells(box)
	asset.AsRunFigures(nodes, attrs, regions, pages, cand, cbytes, assets, uses, abytes, 4194304, 33554432, 0, 150, 4194304, 3, 1234, 0, ans, rq, bms, ws, z, rows, tmp, rec, box)
	port.CellsDrop(res, 0)
	port.CellsPush(res, plan.RecCount(rq))
	port.CellsPush(res, model.NodeAttrIntOr(nodes, attrs, n, model.FkNoasset(), -1))
	port.CellsPush(res, model.NodeAttrIntOr(nodes, attrs, n, model.FkAsset(), -1))
	return 0
}

func TestWhichFiguresAreTheImageAndWhichAreRendered(emonT *testing.T) {
	var res *port.Cells = port.NewCells()
	afSource(res, 0)
	port.AssertEq(emonT, port.CellsAt(res, 0), 0, "a whole clean image is its own: no request")
	port.AssertEq(emonT, port.CellsAt(res, 2), 0, "it is asset 0")
	afSource(res, 1)
	port.AssertEq(emonT, port.CellsAt(res, 0), 1, "paint over it (overlaid): rendered, a crop is asked")
	afSource(res, 8)
	port.AssertEq(emonT, port.CellsAt(res, 0), 1, "a clip that is not a rectangle (clip-bbox): rendered")
	afSource(res, 9)
	port.AssertEq(emonT, port.CellsAt(res, 0), 1, "a placement that is not rectilinear (transformed): rendered")
	afSource(res, 2)
	port.AssertEq(emonT, port.CellsAt(res, 0), 1, "colorspace at images is rendered at figures")
	afSource(res, 3)
	port.AssertEq(emonT, port.CellsAt(res, 0), 1, "so is codec")
	afSource(res, 4)
	port.AssertEq(emonT, port.CellsAt(res, 0), 1, "a page-sized image in a PDF is rendered (its pixels need the host's decode-img, D563)")
	afSource(res, 7)
	port.AssertEq(emonT, port.CellsAt(res, 0), 1, "a region candidate is rendered")
	afSource(res, 5)
	port.AssertEq(emonT, port.CellsAt(res, 0), 0, "an image too large is not rendered")
	port.AssertEq(emonT, port.CellsAt(res, 1), model.NzTooLarge(), "it says so")
	afSource(res, 6)
	port.AssertEq(emonT, port.CellsAt(res, 0), 0, "a budget reason is the candidate's own")
	port.AssertEq(emonT, port.CellsAt(res, 1), model.NzBudget(), "it says so")
}

